import{_ as n,l as i,o as e,c as l,v as o,p as s,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"点分治","description":"","frontmatter":{"title":"点分治","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/centroid-decomposition.md","filePath":"cs/centroid-decomposition.md","lastUpdated":1789023840000}'),h={name:"cs/centroid-decomposition.md"};function _(m,a,u,E,f,T){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="点分治" tabindex="-1">点分治 <a class="header-anchor" href="#点分治" aria-label="Permalink to &quot;点分治&quot;">​</a></h1><div class="epigraph"><p>树的重心子树不超过一半；以重心为根分治，路径统计变成「过当前根」与「落在子树」两支，层数 $O(\\log n)$。</p><footer>—— 据 Jordan 的树重心；分治范式见 CLRS 第 4 章；树上点分治为标准教材技法整理</footer></div><p>上一课<a href="/cs/heavy-light">重链剖分</a>把路径变成区间。有一类询问不是「路径聚合」，而是<strong>树上距离/路径计数</strong>：有多少对点距离为 \\(k\\)、路径权 \\(\\le K\\)。HLD 的线段树不直接数点对。缺口是点分治：选重心，统计过根的路径，再对每棵子树递归。不重写重链。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>树（无根）上，重心（centroid）满足：删掉后每棵连通块大小 \\(\\le n/2\\)。存在，且可在 \\(O(n)\\) 内找（两次 DFS 或一次换根）。以重心为根，任意路径要么过根，要么整段落在某子树。过根的用到根距离/权的集合做双指针或排序；子树递归。层数 \\(O(\\log n)\\)，每层扫边 \\(O(n)\\)，总 \\(O(n\\log n)\\) 再乘以层内统计代价。</p><p>缺口是这套分治树，不是再求 LCA。</p><h3 id="重心不是直径中点" tabindex="-1">重心不是直径中点 <a class="header-anchor" href="#重心不是直径中点" aria-label="Permalink to &quot;重心不是直径中点&quot;">​</a></h3><p>直径中点（或中心）与重心不同：一个管偏心距，一个管子树大小。点分治要的是大小平衡，保证递归深度对数。边分治把边当切，层数仍对数，实现更绕，本课点名。</p><p><span class="marginnote">Jordan 19 世纪已讨论树的重心。点分治是分治在树上的实例，主定理的形状：\\(T(n)= \\sum T(n_i)+O(n)\\)，\\(n_i\\le n/2\\)。后课 Kruskal 重构树用 MST 结构回答最大边查询，不是重心。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>找重心；标记已删（虚删）。收集子树到根的信息，容斥：全集统计减去同一子树内的（不过根）。递归未删子树。注意不要把过根路径算重：点对 \\((a,b)\\) 的 \\(lca\\) 在分治树上是某层重心。</p>',11)),(e(),s(p,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E6%89%BE%E9%87%8D%E5%BF%83%22%5D%20--%3E%20STAT%5B%22%E7%BB%9F%E8%AE%A1%E8%BF%87%E6%A0%B9%E8%B7%AF%E5%BE%84%22%5D%0A%20%20STAT%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E5%AD%90%E6%A0%91%22%5D%0A%20%20REC%20--%3E%20C%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>点分治树（centroid tree）深度 \\(O(\\log n)\\)，可当另一棵树预处理。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每次切掉重心，块大小折半，递归树高对数。与<a href="/cs/divide-conquer">分治</a>同型，平衡保证来自重心定义而非输入有序。容斥：过根 = 所有到根的配对减去同一子树内配对。哈希或排序做配对，复杂度随题。</p><p>不要在带环图上找「重心」当点分治：先要块是树。点双连通上的点分治是另一层，不插入。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写点分树套数据结构的全部模板变体。动态点分治（带修改）更重。后课默认：树上点对路径统计可用重心分治。下一课用 Kruskal 重构树回答「路径最大边 \\(\\le x\\)」一类查询。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重心使子树 \\(\\le n/2\\)；路径过根或在子树。</li><li>每层 \\(O(n)\\)，深度 \\(O(\\log n)\\)。</li><li>管点对统计，不是路径区间修改。</li><li>出处：重心见经典图论；分治见 CLRS 第 4 章。</li></ul>',8))])}const S=n(h,[["render",_]]);export{b as __pageData,S as default};
